// 中学受験 社会（小6前半）単元の動く図解スライド（図のなかった単元に1つずつ）。
// 「なぜ？」の連鎖で7枚以上。上に図、下の帯にそのスライドのひとこと。
import type { DiagramFigure } from './figures';
import { show, bx, lb, ar, pg, C, FILL } from './diagram-kit';
import type { DiagramElement } from './figures';
import { fresh } from './diagram-kit';

type El = DiagramElement;
const cap = (t: string, color: string = C.ink, size = 12): El[] => [lb(160, 196, t, size, color, 'middle', true)];
const S = (note: string, els: El[], c: string, color: string = C.ink) => ({ note, add: [...fresh(...els), ...cap(c, color)] });
const q = (t: string): El => lb(160, 16, t, 12, C.red, 'middle', true);
const h = (t: string, color: string = C.ink): El => lb(160, 16, t, 13, color, 'middle', true);
const chain = (labels: string[], y: number, colors: string[], fills: string[], size = 11, bh = 44): El[] => {
  const n = labels.length;
  const gap = 14;
  const w = (300 - gap * (n - 1)) / n;
  const out: El[] = [];
  labels.forEach((t, i) => {
    const x = 10 + i * (w + gap);
    out.push(bx(x, y, w, bh, t, colors[i % colors.length], fills[i % fills.length], size));
    if (i < n - 1) out.push(ar(x + w + 1, y + bh / 2, x + w + gap - 1, y + bh / 2));
  });
  return out;
};
const vstack = (labels: string[], y0: number, colors: string[], fills: string[], size = 11): El[] => {
  const out: El[] = [];
  labels.forEach((t, i) => {
    const y = y0 + i * 32;
    out.push(bx(40, y, 240, 24, t, colors[i % colors.length], fills[i % fills.length], size));
    if (i < labels.length - 1) out.push(ar(160, y + 25, 160, y + 31));
  });
  return out;
};
const B = [C.blue, C.green, C.main, C.purple, C.red];
const F = [FILL.blue, FILL.green, FILL.warm, FILL.purple, FILL.red];

