// ───────── shakai_s265 安土桃山文化 ─────────
const castle = (x: number, y: number, c: string, f: string): El[] => [
  pg([[x, y + 50], [x + 100, y + 50], [x + 100, y + 30], [x, y + 30]], c, f),
  pg([[x + 10, y + 30], [x + 90, y + 30], [x + 80, y + 12], [x + 20, y + 12]], c, f),
  pg([[x + 25, y + 12], [x + 75, y + 12], [x + 65, y], [x + 35, y]], c, f),
];
